import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BwlBv862.js";const v=JSON.parse('{"title":"TikTools 4.2.1-rc.3","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.3","docId":"releases.4.2.1-rc.3","translationKey":"releases.4.2.1-rc.3","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","translationRevision":"374656624c1090e464adbb3c6ac85c1376d73fbc2f5cae094c0d7ccfba35a52b","order":30},"headers":[],"relativePath":"fr/releases/4.2.1-rc.3.md","filePath":"fr/releases/4.2.1-rc.3.md","lastUpdated":1794611623000}'),s={name:"fr/releases/4.2.1-rc.3.md"};function n(o,e,l,c,d,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc3" tabindex="-1">TikTools 4.2.1-rc.3 <a class="header-anchor" href="#tiktools-421-rc3" aria-label="Permalink to &quot;TikTools 4.2.1-rc.3 {#tiktools-421-rc3}&quot;">​</a></h1><h2 id="goal-release-status-and-prerequisites" tabindex="-1">Objectif, état de publication et prérequis <a class="header-anchor" href="#goal-release-status-and-prerequisites" aria-label="Permalink to &quot;Objectif, état de publication et prérequis {#goal-release-status-and-prerequisites}&quot;">​</a></h2><p>RC3 est une préversion publiée, selon le statut du 13 novembre 2026. Utilisez-la pour évaluer les changements du bureau Linux après RC2, avec une sauvegarde et un profil de test distinct. Il s’agit d’une version candidate plutôt que d’une mise à jour du canal stable. Téléchargez l’AppImage, le DEB ou la ressource portable publiée ainsi que son <code>SHA256SUMS.txt</code> depuis la <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">liste des versions</a> ; les paquets consignés ont été compilés localement.</p><p>La récupération des sections Cloud et la collaboration restent expérimentales. L’installation ne déploie pas les migrations serveur et ne démontre pas la compatibilité des comptes en production.</p><h2 id="changes-available-in-rc3" tabindex="-1">Changements disponibles dans RC3 <a class="header-anchor" href="#changes-available-in-rc3" aria-label="Permalink to &quot;Changements disponibles dans RC3 {#changes-available-in-rc3}&quot;">​</a></h2><ul><li>Conserve la correction RC2 des lectures concurrentes de comparaison et la nouvelle tentative locale avec la raison native de l’échec.</li><li>Variables persiste les types texte, nombre, booléen, liste et secret local. Les enregistrements atomiques rejettent un changement d’hôte ou une révision d’éditeur obsolète, tout en préservant le rendu textuel existant des modèles.</li><li>Les secrets restent masqués. Changer d’hôte ne peut pas provoquer un repli vers une écriture ancienne, et la classification native exclut des publications et comparaisons ultérieures les valeurs mises en file avant de devenir secrètes.</li><li>Le pont natif Variables prend en charge la comparaison en cache, l’adoption explicite d’une variable et le téléchargement limité au cache. L’application revérifie la session, le consentement, la révision locale et l’entrée du cache.</li></ul><p>L’enregistrement des Variables reste local. RC3 n’expose pas le bouton complet Variables Changes avec envoi/retrait après examen et gestion des conflits en attente ; cette intégration de section est décrite dans les <a href="./4.2.2.html">notes du code source de 4.2.2</a>. Déclarer secrète une valeur locale n’efface pas une copie Cloud publiée auparavant.</p><h2 id="check-the-published-candidate" tabindex="-1">Vérifier la version candidate publiée <a class="header-anchor" href="#check-the-published-candidate" aria-label="Permalink to &quot;Vérifier la version candidate publiée {#check-the-published-candidate}&quot;">​</a></h2><ol><li>Vérifiez la somme de contrôle du paquet et la version affichée <code>4.2.1-rc.3</code>. Séparez le profil de test et les répertoires XDG de votre profil habituel.</li><li>Créez une variable texte anodine telle que <code>demoGreeting = &quot;Bonjour&quot;</code>, enregistrez-la et rechargez-la. Vérifiez les autres types explicites avec des valeurs d’exemple non sensibles.</li><li>Ouvrez Changes et testez le chargement/la nouvelle tentative locale. Examinez Settings/Teams et l’aide guidée facultative sans considérer les capacités serveur absentes comme une configuration réussie.</li><li>Pour tout échec, signalez l’action exacte, la version, la raison native et l’identifiant de requête. Excluez les jetons, codes d’invitation et valeurs secrètes des rapports.</li></ol><h2 id="expected-result-evidence-and-recovery" tabindex="-1">Résultat attendu, preuves et récupération <a class="header-anchor" href="#expected-result-evidence-and-recovery" aria-label="Permalink to &quot;Résultat attendu, preuves et récupération {#expected-result-evidence-and-recovery}&quot;">​</a></h2><p>Les valeurs locales typées doivent survivre au rechargement, tandis que les modifications avec un hôte ou une révision obsolètes échouent visiblement. Le rapport original indique des vérifications natives Variables/synchronisation/parité, des tests navigateur avec faux hôte, une vérification de CLI en bac à sable, des vérifications du contenu des installateurs et un démarrage atteignant frontend-ready avec un profil isolé vide. Il ne démontre ni la synchronisation en production avec un compte connecté ni la lecture multimédia.</p><p>Le SHA-256 AppImage enregistré est <code>4b11260836457350debf2680b230c52cea8408ddf17ccdc729d0025a62149b7e</code> ; vérifiez le fichier de sommes de contrôle accompagnant votre téléchargement. En cas d’échec, préservez le profil copié et utilisez le <a href="./../user/preferences/troubleshooting.html">dépannage</a> avant de réessayer les actions de récupération.</p><p>Les invitations par pseudonyme dépendent du serveur <code>6a69c99</code> et de la migration <code>20261113000001_remote_invitation_recipients.sql</code>. L’ancien rapport observait une route de personnes manquante ; aucune nouvelle vérification en production n’est revendiquée ici. Le transport Cloud Automations, les révisions Overlay et l’audit restant de collaboration étaient inachevés, et le détenteur historique du verrou SQLite restait inconnu.</p><p>Le <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.3.md" target="_blank" rel="noreferrer">rapport de version original</a> est conservé comme preuve datée. Revenez à l’<a href="./">index des versions</a>.</p>',14)])])}const h=a(s,[["render",n]]);export{v as __pageData,h as default};
